import{_ as i,a0 as r,w as l,s,ao as d,I as o,x as e,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Python 調試技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Python 調試技巧 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 調試技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 調試技巧 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180519 Python Debugging Tips","title":"Python 調試技巧","tag":"201807","desc":""},"relativePath":"201807/20180519 Python Debugging Tips.md","filePath":"[post].md"}'),h={name:"201807/20180519 Python Debugging Tips.md"};function g(u,t,b,m,f,T){const a=r("Link");return l(),s("div",null,[t[15]||(t[15]=d('<h1 id="python-調試技巧" tabindex="-1">Python 調試技巧 <a class="header-anchor" href="#python-調試技巧" aria-label="Permalink to “Python 調試技巧”">​</a></h1><p>當進行調試時，你有很多選擇，但是很難給出一直有效的通用建議（除了“你試過關閉再打開麼？”以外）。</p><p>這裏有一些我最喜歡的 Python 調試技巧。</p><h3 id="建立一個分支" tabindex="-1">建立一個分支 <a class="header-anchor" href="#建立一個分支" aria-label="Permalink to “建立一個分支”">​</a></h3><p>請相信我。即使你從來沒有打算將修改提交回上游，你也會很樂意將你的實驗被包含在它們自己的分支中。</p><p>不説別的，它會使清理更容易！</p><h3 id="安裝-pdb" tabindex="-1">安裝 pdb++ <a class="header-anchor" href="#安裝-pdb" aria-label="Permalink to “安裝 pdb++”">​</a></h3><p>認真地説，如果你使用命令列，它會讓你的生活更輕鬆。</p><p>pdb++ 所做的一切就是用更好的模組替換標準的 pdb 模組。以下是你在 <code>pip install pdbpp</code> 會看到的：</p><ul><li>彩色提示！</li><li>製表符補全！（非常適合探索！）</li><li>支持切分！</li></ul><p>好的，也許最後一個是有點多餘……但是非常認真地説，安裝 pdb++ 非常值得。</p><h3 id="探索" tabindex="-1">探索 <a class="header-anchor" href="#探索" aria-label="Permalink to “探索”">​</a></h3><p>有時候最好的辦法就是胡亂試試，然後看看會發生什麼。在“明顯”的位置放置一個斷點並確保它被命中。在代碼中加入 <code>print()</code> 和/或 <code>logging.debug()</code> 語句，並查看代碼執行的位置。</p><p>檢查傳遞給你的函數的參數，檢查庫的版本（如果你已經非常絕望了）。</p><h3 id="一次只能改變一件事" tabindex="-1">一次只能改變一件事 <a class="header-anchor" href="#一次只能改變一件事" aria-label="Permalink to “一次只能改變一件事”">​</a></h3><p>在你在探索了一下後，你將會對你可以做的事情有所瞭解。但在你開始擺弄代碼之前，先退一步，考慮一下你可以改變什麼，然後只改變一件事。</p><p>做出改變後，然後測試一下，看看你是否接近解決問題。如果沒有，請將它改回來，然後嘗試其他方法。</p><p>只更改一件事就可以讓你知道什可以工作，哪些不工作。另外，一旦可以工作後，你的新提交將會小得多（因為將有更少的變化）。</p><p>這幾乎是<ruby>科學過程<rt>Scientific Process</rt></ruby>中所做的事情：一次只更改一個變量。通過讓自己看到並衡量一次更改的結果，你可以節省你的理智，並更快地找到解決方案。</p><h3 id="不要假設-提出問題" tabindex="-1">不要假設，提出問題 <a class="header-anchor" href="#不要假設-提出問題" aria-label="Permalink to “不要假設，提出問題”">​</a></h3><p>偶爾一個開發人員（當然不是你咯！）會匆忙提交一些有問題的代碼。當你去調試這段代碼時，你需要停下來，並確保你明白它想要完成什麼。</p><p>不要做任何假設。僅僅因為代碼在 <code>model.py</code> 文件中並不意味着它不會嘗試渲染一些 HTML。</p><p>同樣，在做任何破壞性的事情之前，仔細檢查你的所有外部關聯。要刪除一些配置數據？<strong>請確保你沒有連接到你的生產系統。</strong></p><h3 id="聰明-但不要聰明過頭" tabindex="-1">聰明，但不要聰明過頭 <a class="header-anchor" href="#聰明-但不要聰明過頭" aria-label="Permalink to “聰明，但不要聰明過頭”">​</a></h3><p>有時候我們編寫的代碼神奇般地奏效，不知道它是如何做的。</p><p>當我們發佈代碼時，我們可能會覺得自己很聰明，但當代碼崩潰時，我們往往會感到愚蠢，我們必須記住它是如何工作的，以便弄清楚它為什麼不起作用。</p><p>留意任何看起來過於複雜、冗長或極短的代碼段。這些可能是隱藏複雜並導致錯誤的地方。</p><hr>',28)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),p(a,{href:"https://pythondebugging.com/articles/python-debugging-tips"},{default:n(()=>[...t[0]||(t[0]=[e("https://pythondebugging.com/articles/python-debugging-tips",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=e("作者：",-1)),p(a,{href:"https://pythondebugging.com"},{default:n(()=>[...t[2]||(t[2]=[e("PythonDebugging.com",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),p(a,{href:"https://github.com/geekpi"},{default:n(()=>[...t[4]||(t[4]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=e("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}co